events.code:
; About thirty times a second: what happens as time goes by.
; eng is the game, t the tick (t.Time, t.Dt, t.Keys, t.Pressed, t.Hits).
if (Play.HurtUntil && t.Time > Play.HurtUntil) {
    Play.HurtUntil := 0
    eng.Set("hero", {Flash: false})
}
if (Play.TalkUntil && t.Time > Play.TalkUntil) {
    Play.TalkUntil := 0
    eng.Hud("talk")
}
; fainted: Enter wakes Aria up in the village, with half her gold
if (Play.Over && t.Pressed.Has("enter")) {
    Play.Over := false
    Hero.HP := Hero.MaxHP, Hero.Gold := Hero.Gold // 2
    eng.Set("hero", {X: 8.5, Y: 11.5, Frozen: false})
    eng.Hud("big")
    AxBindSync()
    Say("Aria wakes up by the well, a little poorer.")
}
; a new slime now and then, while the meadow is quiet
if (Play.SlimeHp.Count < 4 && t.Time > Play.RespawnAt) {
    Play.RespawnAt := t.Time + 6
    x := Random(22, 37), y := Random(10, 23), ch := eng.TileAt(x, y)
    if (ch = "." || ch = ",")
        AddSlime(x + 0.5, y + 0.5)
}
